<?php require_once __DIR__.'/includes/functions.php'; $token=trim($_GET['token']??''); $s=db()->prepare("SELECT r.*,c.course_code,c.course_title,c.level,c.semester,GROUP_CONCAT(l.full_name ORDER BY l.id SEPARATOR ', ') lecturer_name,s.stage_name,o.office_name FROM result_records r JOIN courses c ON c.id=r.course_id JOIN course_lecturers cl ON cl.course_id=c.id JOIN lecturers l ON l.id=cl.lecturer_id JOIN status_stages s ON s.id=r.current_stage_id LEFT JOIN offices o ON o.id=r.current_office_id WHERE r.public_token=? GROUP BY r.id");$s->execute([$token]);$r=$s->fetch(); if(!$r){http_response_code(404);exit('Tracking record not found.');}$m=db()->prepare('SELECT rm.*,sf.stage_name from_stage,st.stage_name to_stage FROM result_movements rm LEFT JOIN status_stages sf ON sf.id=rm.from_stage_id JOIN status_stages st ON st.id=rm.to_stage_id WHERE rm.result_id=? ORDER BY rm.moved_at ASC,rm.id ASC');$m->execute([$r['id']]);$moves=$m->fetchAll();$stages=db()->query('SELECT stage_order,stage_name FROM status_stages WHERE stage_order BETWEEN 1 AND 7 ORDER BY stage_order')->fetchAll();$currentOrder=(int)db()->query("SELECT stage_order FROM status_stages WHERE id=".(int)$r['current_stage_id'])->fetchColumn();$isReturned=stripos($r['stage_name'],'Returned to Lecturer')!==false || stripos($r['stage_name'],'Query')!==false;
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Track <?=e($r['course_code'])?> | IFT</title><link rel="icon" href="favicon.ico"><link rel="stylesheet" href="css/style.css"></head><body><header class="site-header"><div class="container nav-wrap"><a class="brand" href="index.php"><img src="assets/naits-logo.png" class="brand-logo"><span class="brand-divider"></span><span class="brand-text">Department of<br>Information Technology</span></a><nav class="main-nav desktop-nav"><a href="index.php">Home</a><a class="active" href="index.php#search">Track Result</a><a href="index.php#about">About</a></nav><a class="help-link" href="index.php#help"><span class="help-icon">?</span><span>Need Help?</span></a></div></header><main><section class="page-hero"><div class="container"><span class="eyebrow dark">PUBLIC RESULT TRACKING</span><h1><?=e($r['course_title'])?></h1><p><?=e($r['course_code'])?> · <?=e($r['level'])?> Level · <?=e($r['semester'])?> · <?=e($r['session_name'])?></p></div></section><section class="page-section"><div class="container two-col"><div class="panel"><div class="panel-head"><div><span class="kicker">CURRENT STATUS</span><h2><?=e($r['stage_name'])?></h2><p>Currently with <?=e($r['office_name']??'the department')?></p></div><span class="status-pill"><?=stripos($r['stage_name'],'Released')!==false?'Completed':'In Progress'?></span></div><div class="info-grid"><div><span>Course Code</span><strong><?=e($r['course_code'])?></strong></div><div><span>Lecturer</span><strong><?=e($r['lecturer_name'])?></strong></div><div><span>Level</span><strong><?=e($r['level'])?> Level</strong></div><div><span>Semester</span><strong><?=e($r['semester'])?></strong></div><div><span>Session</span><strong><?=e($r['session_name'])?></strong></div><div><span>Since</span><strong><?=e(date('d M Y · h:i A',strtotime($r['current_since'])))?></strong></div></div></div><div class="panel"><div class="panel-head"><div><span class="kicker">TRACKING TIMELINE</span><h2>Result journey</h2></div></div><?php if($isReturned):?><div class="returned-notice"><strong>Result returned to lecturer</strong><span>The result was queried and sent back. The normal progress stages are not marked as completed while the query is being resolved.</span></div><?php endif;?><div class="timeline"><?php foreach($stages as $stage):$n=(int)$stage['stage_order'];$done=!$isReturned && ($n<$currentOrder || ($n===$currentOrder && stripos($r['stage_name'],'Released')!==false));$active=!$isReturned && $n===$currentOrder;?><div class="timeline-item <?=$done?'done':''?> <?=$active?'active':''?>"><span class="timeline-dot"><?=$done?'✓':$n?></span><div><strong><?=e($stage['stage_name'])?></strong><small><?php if($isReturned):?>Returned to lecturer — query in progress<?php elseif($active):?>Current stage — <?=e(date('d M Y · h:i A',strtotime($r['current_since'])))?><?php elseif($done):?>Completed<?php else:?>Pending<?php endif;?></small></div></div><?php endforeach;?></div></div></div><div class="panel" style="margin-top:20px"><div class="panel-head"><div><span class="kicker">MOVEMENT HISTORY</span><h2>Recorded handovers</h2></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Stage</th><th>Movement</th></tr></thead><tbody><?php foreach($moves as $mv):?><tr><td><?=e(date('d M Y · h:i A',strtotime($mv['moved_at'])))?></td><td><?=e($mv['to_stage'])?></td><td><?=e($mv['from_stage']?($mv['from_stage'].' → '.$mv['to_stage']):$mv['to_stage'])?></td></tr><?php endforeach;?></tbody></table></div></div></section></main><footer class="site-footer"><div class="container footer-inner"><p>© 2026 Department of Information Technology (IFT). All rights reserved.</p></div></footer></body></html>
